#!/usr/bin/env bash
set -euo pipefail

PG_BIN="${PG_BIN:-/usr/local/opt/postgresql@17/bin}"
case "$PG_BIN" in
  /*) ;;
  *) echo "PG_BIN must be an absolute local PostgreSQL binary directory." >&2; exit 64 ;;
esac
for bin in initdb pg_ctl createdb psql; do
  if [ ! -x "$PG_BIN/$bin" ]; then
    echo "Missing PostgreSQL binary: $PG_BIN/$bin" >&2
    exit 64
  fi
done

# This harness must never inherit a libpq service, host, database, or password.
unset DATABASE_URL PGHOST PGHOSTADDR PGSERVICE PGSERVICEFILE PGDATABASE PGUSER PGPORT PGPASSWORD PGPASSFILE
unset PGCONNECT_TIMEOUT PGOPTIONS PGSSLMODE PGSSLROOTCERT PGSSLCERT PGSSLKEY PGSSLCRL PGREQUIRESSL
unset PGTARGETSESSIONATTRS PGLOADBALANCEHOSTS PGCHANNELBINDING PGGSSENCMODE PGAPPNAME PGCLIENTENCODING
ROOT=$(mktemp -d /tmp/norixo-contact-form-preflight-pg.XXXXXX)
DATA="$ROOT/data"; SOCKET="$ROOT/socket"; PORT=55441; DB=a4_d8_7
case "$ROOT" in /tmp/norixo-contact-form-preflight-pg.*) ;; *) echo "Unexpected temporary cluster path: $ROOT" >&2; exit 64 ;; esac
cleanup() { "$PG_BIN/pg_ctl" -D "$DATA" -m immediate stop >/dev/null 2>&1 || true; rm -rf "$ROOT"; }
trap cleanup EXIT INT TERM
mkdir -m 700 "$DATA" "$SOCKET"
"$PG_BIN/initdb" --auth=trust --no-locale --encoding=UTF8 -D "$DATA" >/dev/null
"$PG_BIN/pg_ctl" -D "$DATA" -o "-h '' -k '$SOCKET' -p $PORT" -w start >/dev/null
"$PG_BIN/createdb" -h "$SOCKET" -p "$PORT" "$DB"
psql() { "$PG_BIN/psql" -X -v ON_ERROR_STOP=1 -h "$SOCKET" -p "$PORT" -d "$DB" "$@"; }
psql <<'SQL' >/dev/null
create extension pgcrypto; create schema auth;
